for(const scenario of ['aggregate-shortage','individual-shortage','season','type','missing-type','missing-row-num','duplicate-row','duplicate-item','no-allowed-pack','in-stock','zero-stock','non-unit-gain'])test('material coverage distinguishes '+scenario+' without manufacturing stock',async t=>{
 const f=multipleProductionFixture(t);let expected='UNKNOWN';
 if(scenario==='aggregate-shortage'){f.state.stock.set('原料自选包',2);expected='INSUFFICIENT';}
 if(scenario==='individual-shortage'){f.state.stock.set('原料自选包',1);expected='INSUFFICIENT';}
 if(scenario==='season'){f.options.config.tables.SelectPackLibCfg.data.find(r=>r.selectItemId==='鱼').season=2;expected='BLOCKED';}
 if(scenario==='type')f.options.config.tables.ItemCfg.data.find(r=>r.id==='鱼').type='货币';
 if(scenario==='missing-type')delete f.options.config.tables.ItemCfg.data.find(r=>r.id==='鱼').type;
 if(scenario==='missing-row-num')delete f.options.config.tables.SelectPackLibCfg.data.find(r=>r.selectItemId==='鱼').num;
 if(scenario==='duplicate-row')f.options.config.tables.SelectPackLibCfg.data.push(clone(f.options.config.tables.SelectPackLibCfg.data.find(r=>r.selectItemId==='鱼')));
 if(scenario==='duplicate-item')f.options.config.tables.ItemCfg.data.push(clone(f.options.config.tables.ItemCfg.data.find(r=>r.id==='鱼')));
 if(scenario==='no-allowed-pack'){f.options.config.tables.BuildingProduceCfg.data[0].costItem.push(['unowned',1]);expected='BLOCKED';}
 if(scenario==='in-stock'){f.state.stock.set('木材',2);f.state.stock.set('鱼',1);expected='IN_STOCK';}
 if(scenario==='zero-stock'){f.state.stock.set('原料自选包',0);expected='INSUFFICIENT';}
 if(scenario==='non-unit-gain'){f.options.config.tables.SelectPackLibCfg.data.find(r=>r.selectItemId==='木材').num=3;expected='COVERED';}
 const before=new Map(f.state.stock),result=await f.service.readMaterialProductionCoverage(f.session,coverageTarget);assert.equal(result.coverage.status,expected,JSON.stringify(result.coverage));assert.equal(result.coverage.ok,expected==='COVERED');assert.equal(result.coverage.reliable,expected!=='UNKNOWN');assert.equal(result.executable,false);assert.equal(result.coverage.executable,false);if(expected!=='COVERED')assert.deepEqual(result.coverage.exchanges,[]);else assert.equal(result.coverage.exchanges[0].num,1);assert.deepEqual(f.state.stock,before);assert.equal(f.state.writes.length,0);assert.deepEqual(f.durable.list(f.session.id),[]);
});
